{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "DenyNoEncryption",
    "Effect": "Deny",
    "Principal": "*",
    "Action": "s3:PutObject",
    "Resource": "arn:aws:s3:::acme-prod-data/*",
    "Condition": {
      "Null": { "s3:x-amz-server-side-encryption": "true" }
    }
  }]
}

aws s3api put-bucket-policy --bucket acme-prod-data \
  --policy file://bucket-policy.json
